window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-41321efd7d5bb390"]={"versions": [{"id": "FIG-41321efd7d5bb390", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Kommunikations-Hardware-Ports im AUTOSAR-Metamodell der ECU-Ressourcenbeschreibung (AUTOSAR_ResourceTemplateECU). Es spezifiziert die statische Struktur zur Beschreibung physikalischer Schnittstellen, Übertragungsmedien und Übertragungsgeschwindigkeiten einer Steuergeräte-Hardware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><strong>CommunicationHWPort</strong>: Spezialisierung bzw. Ausprägung von <code>PeripheralHWPort</code> (im Diagrammkopf referenziert).\n<ul class=\"fig-list\"><li>Komposition zu <code>CommunicationPhysicalMedium</code> mit Rollenname <code>+physicalLayer</code> und Kardinalität <code>0..1</code>.\n</li><li>Komposition zu <code>CommunicationSpeed</code> mit Rollenname <code>+speed</code> und Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>CommunicationPeripheral</strong>: Spezialisierung von <code>Peripheral</code>.\n<ul class=\"fig-list\"><li>Steht in Kompositionsbeziehung von <code>CommunicationHWPort</code> mit Rollenname <code>+hwPort</code> und Kardinalität <code>0..*</code>.\n</li></ul>\n</li><li><strong>CommunicationPhysicalMedium</strong>: Beschreibt die physikalische Schnittstelle mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ physicalMediumType: Enumeration{ELECTRICAL, OPTICAL, WIRELESS} [0..1]</code>\n</li><li><code>+ physicalMediumStandard: String [0..1]</code>\n</li><li><code>+ physicalMediumDataLines: Int [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationSpeed</strong>: Abstrakte Basisklasse für Geschwindigkeitsangaben mit Attribut:\n<ul class=\"fig-list\"><li><code>+ tolerance: Float [0..1]</code>\n</li><li>Dient als Generalisierung für drei spezialisierte Ausprägungen:\n<ul class=\"fig-list\"><li><strong>CommunicationSpeedFixed</strong>: Attribut <code>+ fixSpeed: Int</code>\n</li><li><strong>CommunicationSpeedRange</strong>: Attribute <code>+ minSpeed: Int</code>, <code>+ maxSpeed: Int</code>\n</li><li><strong>CommunicationSpeedList</strong>: Attribut <code>+ speed: Int [1..*]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Laufzeitsequenzen ab. Instanzen der Klassen werden zur Entwurfs- bzw. Konfigurationszeit zur deklarativen Beschreibung der Hardware-Eigenschaften einer ECU instanziiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert normative Vorgaben für die Modellierung von Kommunikationsschnittstellen:</p>\n<ul class=\"fig-list\"><li>Jeder <code>CommunicationHWPort</code> erfordert zwingend genau eine Spezifikation der Übertragungsgeschwindigkeit (<code>+speed: CommunicationSpeed [1]</code>), realisiert über einen festen Wert (<code>fixSpeed</code>), einen Wertebereich (<code>minSpeed</code>/<code>maxSpeed</code>) oder eine Liste diskreter Geschwindigkeiten (<code>speed [1..*]</code>).\n</li><li>Die Zuordnung eines physikalischen Mediums (<code>CommunicationPhysicalMedium</code>) ist optional (<code>0..1</code>).\n</li><li>Ein <code>CommunicationPeripheral</code> aggregiert null bis beliebig viele Hardware-Ports (<code>+hwPort: 0..*</code>).\n</li><li>Alle Geschwindigkeits- und Leitungsparameter nutzen Standard-Datentypen (<code>Int</code>, <code>Float</code>, <code>String</code>) sowie eine geschlossene Enumeration für das Medium (<code>ELECTRICAL</code>, <code>OPTICAL</code>, <code>WIRELESS</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b85137223647aed2", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Kommunikations-Hardware-Ports im AUTOSAR-Metamodell der ECU-Ressourcenbeschreibung (AUTOSAR_ResourceTemplateECU). Es spezifiziert die statische Struktur zur Beschreibung physikalischer Schnittstellen, Übertragungsmedien und Übertragungsgeschwindigkeiten einer Steuergeräte-Hardware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><strong>CommunicationHWPort</strong>: Spezialisierung bzw. Ausprägung von <code>PeripheralHWPort</code> (im Diagrammkopf referenziert).\n<ul class=\"fig-list\"><li>Komposition zu <code>CommunicationPhysicalMedium</code> mit Rollenname <code>+physicalLayer</code> und Kardinalität <code>0..1</code>.\n</li><li>Komposition zu <code>CommunicationSpeed</code> mit Rollenname <code>+speed</code> und Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>CommunicationPeripheral</strong>: Spezialisierung von <code>Peripheral</code>.\n<ul class=\"fig-list\"><li>Steht in Kompositionsbeziehung von <code>CommunicationHWPort</code> mit Rollenname <code>+hwPort</code> und Kardinalität <code>0..*</code>.\n</li></ul>\n</li><li><strong>CommunicationPhysicalMedium</strong>: Beschreibt die physikalische Schnittstelle mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ physicalMediumType: Enumeration{ELECTRICAL, OPTICAL, WIRELESS} [0..1]</code>\n</li><li><code>+ physicalMediumStandard: String [0..1]</code>\n</li><li><code>+ physicalMediumDataLines: Int [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationSpeed</strong>: Abstrakte Basisklasse für Geschwindigkeitsangaben mit Attribut:\n<ul class=\"fig-list\"><li><code>+ tolerance: Float [0..1]</code>\n</li><li>Dient als Generalisierung für drei spezialisierte Ausprägungen:\n<ul class=\"fig-list\"><li><strong>CommunicationSpeedFixed</strong>: Attribut <code>+ fixSpeed: Int</code>\n</li><li><strong>CommunicationSpeedRange</strong>: Attribute <code>+ minSpeed: Int</code>, <code>+ maxSpeed: Int</code>\n</li><li><strong>CommunicationSpeedList</strong>: Attribut <code>+ speed: Int [1..*]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Laufzeitsequenzen ab. Instanzen der Klassen werden zur Entwurfs- bzw. Konfigurationszeit zur deklarativen Beschreibung der Hardware-Eigenschaften einer ECU instanziiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert normative Vorgaben für die Modellierung von Kommunikationsschnittstellen:</p>\n<ul class=\"fig-list\"><li>Jeder <code>CommunicationHWPort</code> erfordert zwingend genau eine Spezifikation der Übertragungsgeschwindigkeit (<code>+speed: CommunicationSpeed [1]</code>), realisiert über einen festen Wert (<code>fixSpeed</code>), einen Wertebereich (<code>minSpeed</code>/<code>maxSpeed</code>) oder eine Liste diskreter Geschwindigkeiten (<code>speed [1..*]</code>).\n</li><li>Die Zuordnung eines physikalischen Mediums (<code>CommunicationPhysicalMedium</code>) ist optional (<code>0..1</code>).\n</li><li>Ein <code>CommunicationPeripheral</code> aggregiert null bis beliebig viele Hardware-Ports (<code>+hwPort: 0..*</code>).\n</li><li>Alle Geschwindigkeits- und Leitungsparameter nutzen Standard-Datentypen (<code>Int</code>, <code>Float</code>, <code>String</code>) sowie eine geschlossene Enumeration für das Medium (<code>ELECTRICAL</code>, <code>OPTICAL</code>, <code>WIRELESS</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-41321efd7d5bb390", "to": "FIG-b85137223647aed2", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
